// ============================================================================
// src/lib/tools/lacp-hash-and-state-reader/golden-vectors.ts
// ----------------------------------------------------------------------------
// GOLDEN VECTORS for the LACP member link and state reader.
//
// Every expected hash, member, intermediate value, spread, state form, status,
// finding and timer below was derived on 2026-11-08 by a separate Python
// oracle (oracle.py, in the build's work folder), not by running this engine:
//   - the link vectors by the Linux bonding driver's code as read that day
//     (drivers/net/bonding/bond_main.c and the headers it uses), with the
//     addresses and ports read by struct.unpack in the processor's byte order
//     ('<I' little-endian, '>I' big-endian) and the addresses parsed by
//     Python's ipaddress module; its big-endian results agree with the Learn
//     lab's own vectors (src/lib/labs/lacp-hashing: F1's layer3+4 hash
//     0x62d3e15a, worked there by hand, and its members);
//   - the state vectors by the bit order of the IEEE8023-LAG-MIB and the Linux
//     LACP_STATE masks, RFC 3417's BITS rule for the SNMP form, Extreme's
//     ATGSCDFE legend and Arista's letters, with the findings and the timers
//     by the rules in compute.ts's header, written again in Python.
// The tables were written from the oracle's output by gen_vectors.py, so no
// expected value was typed by hand; every one of the 256 octets is pinned as
// an actor. The refusals and the sentences that carry the rules are written out
// at the end, each with the rule it pins. The page's Examples and samples
// (examples.ts) are pinned by the vectors that reference their objects.
// GOLDEN_VECTOR_SET_ID changes whenever a vector changes (the api-sync rule).
//
// Second set (2026-11-08b): Huawei's PortState (display eth-trunk). The tables
// HUAWEI_TABLE and HUAWEI_SWEEP were written by a second Python oracle,
// oracle_huawei.py (in the second set's work folder), from Huawei's command
// reference as read in a browser that day: a PortState is the octet with Bit 1
// (its first character) as bit 0, so the string reversed and read as binary;
// a pasted output's Local and Partner rows split on whitespace by their shape;
// the verdict, findings and timers from the first oracle's state rules. Every
// one of the 256 octets is pinned as a PortState too. The refusals, the header
// fields as Huawei's example prints them, the Status words and the notes are
// written out at the end. One first-set expectation changed: err-format names
// five formats now that huawei is one. The order-* vectors pin, from the first
// oracle, that both byte orders choose the same member with 2 and 4 members and
// not with 3 or 5 (the two folds of bond_ip_hash leave the XOR of the word's
// four bytes in its lowest byte; a modulo by a power of two reads only that).
// ============================================================================

import { run, runApi, type LacpRequest, type LacpResult, type LinkResult, type StateResult } from "./compute"; // the engine's API entries
import { EXAMPLE_LINK_REQUEST, EXAMPLE_STATE_REQUEST, LINK_SAMPLES, STATE_SAMPLES, HUAWEI_DISPLAY_EXAMPLE } from "./examples"; // the page's Examples and samples, pinned below

/** The set id: dated, changed with any vector (scripts/check-api-sync.mjs compares it with scripts/api-sync.json). */
export const GOLDEN_VECTOR_SET_ID = "lacp-hash-and-state-reader-golden-2026-11-08b"; // the second set: Huawei's PortState

/** One vector: a request (or raw API text), and either the fields expected or the error expected. */
export interface LacpVector {
  /** A stable id. */
  id: string;
  /** Where the expected values come from. */
  note: string;
  /** The request object (run()). */
  request?: LacpRequest;
  /** Or the raw API body (runApi()). */
  api?: string;
  /** The fields expected (a subset of the reading; objects compared as subsets, arrays element by element). */
  expect?: Record<string, unknown>;
  /** Text the reading's sentences must contain. */
  contains?: { notes?: string[]; findings?: string[]; verdictText?: string; bits?: string[]; statusTexts?: string[] };
  /** The error expected, as a pattern over its message. */
  expectError?: RegExp;
}

/** The page's Examples and samples (D-83), shared with the component through examples.ts and re-exported here. */
export { EXAMPLE_LINK_REQUEST, EXAMPLE_STATE_REQUEST, LINK_SAMPLES, STATE_SAMPLES, HUAWEI_DISPLAY_EXAMPLE }; // the objects the page fills

