/** The link rows as vectors. */
const LINK_VECTORS: readonly LacpVector[] = LINK_TABLE.map(([id, request, hash, member, ifDown, steps, counts, first]) => ({
  id, // the row's id
  note: "Oracle: the Linux transmit hash (bond_main.c) in Python, bytes read by struct.unpack in the processor's byte order.", // the derivation
  request, // the flow
  expect: { mode: "link", hash, member, ifDown, steps: steps.map((value) => ({ value })), ...(counts ? { spread: { counts, first } } : {}) }, // what must come out
})); // link vectors

/** The state rows as vectors. */
const STATE_VECTORS: readonly LacpVector[] = STATE_TABLE.map(([id, request, hex, snmp, extreme, set, partnerHex, status, findings, timers]) => ({
  id, // the row's id
  note: "Oracle: the LACPDU state bit order (IEEE8023-LAG-MIB, Linux LACP_STATE masks), RFC 3417 for SNMP, and the findings and timers in Python.", // the derivation
  request, // the values
  expect: { mode: "state", actor: { hex, snmp, extreme }, partner: partnerHex === null ? null : { hex: partnerHex }, status, findings: findings.map((x) => ({ id: x })), timers, bitsSet: set }, // what must come out (bitsSet is checked separately)
})); // state vectors

/** The Huawei rows as vectors. */
const HUAWEI_VECTORS: readonly LacpVector[] = HUAWEI_TABLE.map(([id, request, hex, huawei, snmp, partnerHex, status, findings, timers, members, port]) => ({
  id, // the row's id
  note: "Second oracle: Huawei's PortState, Bit 1 first (the string reversed and read as binary), rows split by shape; the first oracle's verdict, findings and timers.", // the derivation
  request, // the values or the pasted output
  expect: { mode: "state", format: "huawei", actor: { hex, huawei, snmp }, partner: partnerHex === null ? null : { hex: partnerHex }, status, findings: findings.map((x) => ({ id: x })), timers, huawei: members === null ? null : { port, members: members.map(([p, st, h, ph, vd]) => ({ port: p, status: st, hex: h, partner: ph === null ? null : { hex: ph }, verdict: vd })) } }, // what must come out
})); // Huawei vectors

/** Every octet read back from Huawei's PortState, and shown in it. */
const HUAWEI_SWEEP_VECTORS: readonly LacpVector[] = HUAWEI_SWEEP.map(([ps, hex]) => ({
  id: `huawei-sweep-${ps}`, // the PortState
  note: "Second oracle: the octet whose bit i is the PortState's character i + 1.", // the derivation
  request: { mode: "state", format: "huawei", actor: ps }, // the PortState alone
  expect: { actor: { hex, huawei: ps } }, // read, and shown again as printed
})); // the sweep

