/** Every vector, in order. */
export const LACP_VECTORS: readonly LacpVector[] = Object.freeze([...LINK_VECTORS, ...STATE_VECTORS, ...HUAWEI_VECTORS, ...HUAWEI_SWEEP_VECTORS, ...OTHER_VECTORS]); // tables first, then the rest

/**
 * Whether `actual` holds `expected`: objects as subsets, arrays of the same length element by element, anything else
 * exactly as JSON.
 * @param actual the reading's value
 * @param expected the vector's value
 * @returns true when it matches
 */
function matches(actual: unknown, expected: unknown): boolean {
  if (Array.isArray(expected)) { // a list
    if (!Array.isArray(actual) || actual.length !== expected.length) return false; // the same length
    return expected.every((e, i) => matches(actual[i], e)); // each element
  } // array
  if (expected !== null && typeof expected === "object") { // a subset object
    if (actual === null || typeof actual !== "object") return false; // nothing to compare with
    return Object.entries(expected as Record<string, unknown>).every(([k, v]) => matches((actual as Record<string, unknown>)[k], v)); // each field
  } // object
  return JSON.stringify(actual) === JSON.stringify(expected); // exact, as JSON
} // matches

/** The report verifyVectors returns. */
export interface VerifyReport {
  /** The set id. */
  setId: string;
  /** Vectors run. */
  total: number;
  /** Vectors that passed. */
  passed: number;
  /** One line per failure (empty when all pass). */
  failures: string[];
}

/**
 * Run every vector, and check that the page's Examples and samples are among them.
 * @returns the report (failures empty when all pass)
 */
export function verifyVectors(): VerifyReport {
  const failures: string[] = []; // collected
  for (const v of LACP_VECTORS) { // each vector
    let r: LacpResult | null = null; // the reading
    try {
      r = v.api !== undefined ? runApi(v.api) : run(v.request as LacpRequest); // the API text or the request
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e); // the refusal
      if (!v.expectError) failures.push(`${v.id}: unexpected error: ${msg}`); // should have computed
      else if (!v.expectError.test(msg)) failures.push(`${v.id}: error mismatch: ${msg}`); // the wrong refusal
      continue; // next vector
    } // ran
    if (v.expectError) { failures.push(`${v.id}: expected an error, got a reading`); continue; } // should have refused
    const { bitsSet, ...rest } = (v.expect ?? {}) as Record<string, unknown>; // the bits set are checked from the bit list
    if (!matches(r, rest)) failures.push(`${v.id}: fields differ: ${JSON.stringify(r).slice(0, 400)}`); // a value moved
    if (bitsSet !== undefined && r.mode === "state") { // the bits set, by name
      const got = (r as StateResult).actor.bits.filter((b) => b.set).map((b) => b.name); // as the engine reads them
      if (JSON.stringify(got) !== JSON.stringify(bitsSet)) failures.push(`${v.id}: bits differ: ${got.join(",")}`); // a bit moved
    } // bits
    const c = v.contains ?? {}; // the texts expected
    for (const t of c.notes ?? []) if (!(r as { notes: string[] }).notes.some((n) => n.includes(t))) failures.push(`${v.id}: no note contains "${t}"`); // notes
    if (r.mode === "state") { // the state's sentences
      const st = r as StateResult; // typed
      for (const t of c.findings ?? []) if (!st.findings.some((f) => f.text.includes(t))) failures.push(`${v.id}: no finding contains "${t}"`); // findings
      if (c.verdictText && !st.verdictText.includes(c.verdictText)) failures.push(`${v.id}: verdict lacks "${c.verdictText}"`); // the verdict
      for (const t of c.bits ?? []) if (!st.actor.bits.some((b) => b.text.includes(t))) failures.push(`${v.id}: no bit text contains "${t}"`); // bit meanings
      for (const t of c.statusTexts ?? []) if (!(st.huawei?.members ?? []).some((m) => m.statusText.includes(t))) failures.push(`${v.id}: no Status text contains "${t}"`); // Huawei's Status words
    } // state
    void (r as LinkResult); // the link reading needs no sentence checks beyond notes
  } // vectors
  const ids = new Set(LACP_VECTORS.filter((v) => v.request !== undefined).map((v) => v.request)); // the request objects pinned
  for (const [name, obj] of [["EXAMPLE_LINK_REQUEST", EXAMPLE_LINK_REQUEST], ["EXAMPLE_STATE_REQUEST", EXAMPLE_STATE_REQUEST], ...LINK_SAMPLES.map((x) => [`LINK_SAMPLES ${x.id}`, x.request]), ...STATE_SAMPLES.map((x) => [`STATE_SAMPLES ${x.id}`, x.request])] as [string, unknown][]) { // every object the page fills
    if (!ids.has(obj as LacpRequest)) failures.push(`${name}: not pinned by a vector`); // D-83: the Example is a vector
  } // examples
  return { setId: GOLDEN_VECTOR_SET_ID, total: LACP_VECTORS.length, passed: LACP_VECTORS.length - new Set(failures.map((f) => f.split(":")[0])).size, failures }; // the report
} // verifyVectors
